function renderBuildList(){
  const list = document.getElementById('blist');
  const note = document.getElementById('bnote');
  const owned = nCarts('workshop') > 0;
  if (!owned){
    note.textContent = 'Bolt on the WORKSHOP first. It unlocks every other car.';
    note.classList.remove('hide');
  } else if (inZone('workshop')){
    note.textContent = 'Workshop active — pick a car to bolt onto the rear of the train.';
    note.classList.remove('hide');
  } else {
    note.textContent = 'Walk into the workshop car to build more cars.';
    note.classList.remove('hide');
  }
  list.innerHTML = '';
  for (const type in CART_DEFS){
    if (type === 'workshop' && owned) continue;
    const def = CART_DEFS[type];
    let cost = '';
    const icons = { wood:'🪵', coal:'⚫', scrap:'⚙️', food:'🥫' };
    for (const k in def.cost)
      cost += `<i class="${S.inv[k] < def.cost[k] ? 'no' : ''}">${icons[k]}${def.cost[k]}</i>`;
    const el = document.createElement('div'); el.className = 'bitem';
    el.innerHTML = `<div class="ic">${def.icon}</div>
      <div class="info"><b>${def.name}</b><small>${def.desc}</small><div class="cost">${cost}</div></div>
      <button class="bdo ${canBuildType(type) && canAfford(def.cost)?'':'off'}">ADD</button>`;
    el.querySelector('.bdo').onclick = () => buildCart(type);
    list.appendChild(el);
  }
}
function openBuild(){
  const m = document.getElementById('bmodal');
  renderBuildList(); m.classList.remove('hide');
  S.paused = true; S.joy.active = false; S.joy.dx = S.joy.dy = 0;
}
function closeBuild(){
  document.getElementById('bmodal').classList.add('hide');
  S.paused = false;
}
function toggleBuild(){
  if (!canOpenBuild()){
    toast(S.player.aboard ? 'Walk into the workshop car to build' : 'Climb aboard to build');
    return;
  }
  const m = document.getElementById('bmodal');
  if (m.classList.contains('hide')) openBuild();
  else closeBuild();
}
document.getElementById('bclose').onclick = closeBuild;

