const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch();
  const base = 'file://' + path.resolve('index.html');
  const land = await browser.newPage({ viewport: { width: 844, height: 390 }, deviceScaleFactor: 2, hasTouch: true, isMobile: true });
  await land.goto(base); await land.waitForTimeout(500);
  await land.screenshot({ path: '/tmp/opencode/l-title.png' });
  const ovInfo = await land.evaluate(() => {
    const c = document.querySelector('#ovCard').getBoundingClientRect();
    return { cardH: Math.round(c.height), viewH: innerHeight, scrollH: document.querySelector('#ovCard').scrollHeight, clientH: document.querySelector('#ovCard').clientHeight };
  });
  console.log('landscape title card:', ovInfo);
  await land.click('#go'); await land.waitForTimeout(900);
  await land.screenshot({ path: '/tmp/opencode/l-play.png' });

