const { chromium } = require('playwright');
const path = require('path');
const assert = (c, m) => { if (!c) throw new Error('FAIL: ' + m); console.log('ok -', m); };
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  await page.goto('file://' + path.resolve('index.html'));
  await page.waitForTimeout(400);
  await page.click('#go');
  await page.waitForTimeout(1200);

  // stale-HUD regression: play a while, win, retry, HUD must reset right away
  await page.evaluate(() => { S.train.y = S.train.y - 5000; S.mode = 'win'; showOverlay('win'); });
  await page.waitForTimeout(100);
  assert(await page.locator('#ov').isVisible(), 'win overlay visible');
  await page.click('#go');
  await page.waitForTimeout(60);
  const hud = await page.evaluate(() => ({
    dist: document.getElementById('dist').textContent,
    fuel: document.getElementById('fuelN').textContent,
    hp: document.getElementById('hpN').textContent,
    inv: document.getElementById('inv').textContent.replace(/\s+/g, ' ').trim(),
  }));
  console.log('hud after retry:', hud);
  assert(hud.dist.startsWith('0 ') || hud.dist.startsWith('1 '), 'distance HUD resets immediately');
  assert(hud.fuel === '55', 'fuel HUD resets immediately');
  assert(hud.hp === '100', 'health HUD resets immediately');
  assert(/🪵 6/.test(hud.inv), 'inventory HUD resets immediately');

  // pausing blocks actions and freezes the world
  await page.evaluate(() => { S.train.moving = true; S.train.fuel = 70; S.inv = { wood: 6, coal: 2, scrap: 4, food: 1 }; });
  await page.keyboard.press('b');
  await page.waitForTimeout(150);
  assert(await page.evaluate(() => S.paused), 'build pauses');
  const y1 = await page.evaluate(() => S.train.y);
  await page.keyboard.press(' ');
  await page.keyboard.press('t');
  await page.keyboard.press('f');
  await page.waitForTimeout(300);
  const pausedState = await page.evaluate(() => ({ y: S.train.y, aboard: S.player.aboard, coal: S.inv.coal, moving: S.train.moving }));
  console.log('paused state:', pausedState);
  assert(pausedState.aboard, 'Space does not disembark while build menu is open');
  assert(Math.abs(pausedState.y - y1) < .5, 'train frozen while paused');
  assert(pausedState.coal === 2, 'fuel action ignored while paused');
  await page.keyboard.press('Escape');
  await page.waitForTimeout(150);
  assert(await page.evaluate(() => !S.paused), 'Escape closes the build menu');

  // retry after death also clears modal state
  await page.evaluate(() => { S.mode = 'play'; S.player.hp = 1; damage(5); });
  await page.waitForTimeout(100);
  assert(await page.evaluate(() => S.mode === 'dead'), 'death overlay');
  await page.waitForTimeout(300);
  await page.click('#go');
  await page.waitForTimeout(100);
  assert(await page.evaluate(() => S.mode === 'play' && !S.paused && document.getElementById('bmodal').classList.contains('hide')), 'retry clears pause/modal');

  console.log(errors.length ? errors.join('\n') : 'no page errors');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

