const { chromium } = require('playwright');
const path = require('path');
const assert = (c, m) => { if (!c) throw new Error('FAIL: ' + m); console.log('ok -', m); };
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  await page.goto('file://' + path.resolve('index.html'));
  await page.waitForTimeout(400);
  await page.click('#go');
  await page.waitForTimeout(400);

  // joystick: drag left-side up while aboard; player.ly should decrease
  const before = await page.evaluate(() => ({ ly: S.player.ly, lx: S.player.lx, cab: inCab() }));
  await page.mouse.move(100, 650);
  await page.mouse.down();
  await page.mouse.move(100, 540, { steps: 8 });
  await page.waitForTimeout(700);
  const during = await page.evaluate(() => ({ ly: S.player.ly, active: S.joy.active, dx: S.joy.dx, dy: S.joy.dy }));
  await page.mouse.up();
  console.log('joystick:', before, during);
  assert(during.active, 'joystick activates on the left side of the screen');
  assert(during.ly < before.ly - 20, 'joystick walks the player forward on deck');

  // tap BUILD (mobile-style) opens the modal
  await page.locator('#bBuild').tap();
  await page.waitForTimeout(200);
  assert(await page.locator('#bmodal').isVisible(), 'tapping BUILD opens the workshop');
  await page.locator('.bitem').first().locator('.bdo').tap();
  await page.waitForTimeout(200);
  assert(await page.evaluate(() => S.train.carts[0]?.type === 'workshop'), 'tapping ADD builds the workshop');
  assert(await page.evaluate(() => !S.paused), 'game resumes after building first workshop');

  // right-side taps must not steer
  await page.mouse.move(340, 500); await page.mouse.down(); await page.waitForTimeout(100);
  assert(!(await page.evaluate(() => S.joy.active)), 'right-side taps do not activate the joystick');
  await page.mouse.up();

  console.log(errors.length ? errors.join('\n') : 'no page errors');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

