```
function biomeMix(worldY){
  const d = clamp(-worldY/PPM, 0, GOAL_M);
  const W = 160;
  for (let k=1;k<BIOMES.length;k++){
    const B=k*1000;
    if (d > B-W && d < B+W){
      const t = smoothstep((d-(B-W))/(2*W));
      return {a:k-1,b:k,t};
    }
  }
  const i = Math.min(BIOMES.length-1, Math.floor(d/1000));
  return {a:i,b:i,t:0};
}
```
