    ctx.strokeStyle=B.trunk; ctx.lineWidth=4; ctx.lineCap='round';
    ctx.beginPath(); ctx.moveTo(x,y+10); ctx.lineTo(x,y-12); ctx.stroke();
    ctx.lineWidth=2.4;
