function biomeColorCssAt(y, field){
  const m=biomeMix(y);
  if (!m.t) return rgbCss(BIOMES[m.a][field]);
  return rgbCss(mix3(BIOMES[m.a][field], BIOMES[m.b][field], m.t));
}
function biomeGradient(field, y0, y1, n){
  const g=ctx.createLinearGradient(0,y0,0,y1);
  for (let i=0;i<=n;i++){ const y=y0+(y1-y0)*i/n; g.addColorStop(i/n, biomeColorCssAt(y,field)); }
  return g;
}
