const GROUND_DECOR = { grass:1, pool:1, snowdrift:1, crack:1, ashpile:1, drybush:1, reed:1 };
function biomeColorCssAt(y, field){
  const m = biomeMix(y);
  return m.t ? rgbCss(mix3(BIOMES[m.a][field], BIOMES[m.b][field], m.t)) : rgbCss(BIOMES[m.a][field]);
}
function biomeGradient(field, y0, y1, n){
  const g = ctx.createLinearGradient(0, y0, 0, y1);
  for (let i = 0; i <= n; i++){
    const y = y0 + (y1 - y0) * i / n;
    g.addColorStop(i/n, biomeColorCssAt(y, field));
  }
  return g;
}
function propBiome(p){ return BIOMES[biomeIdxAt(p.y)]; }
