    }
  } else if (B.id==='desert'){
    for (let i=-1;i<=1;i++){ ctx.beginPath(); ctx.moveTo(x+i*4,y);
      ctx.lineTo(x+i*5+(i===0?3:0), y-7-s*7); ctx.stroke(); }
  } else if (B.id==='frozen'){
    ctx.strokeStyle='rgba(220,240,250,.75)';
    for (let i=-1;i<=1;i++){ ctx.beginPath(); ctx.moveTo(x+i*4,y); ctx.lineTo(x+i*4+(s-.5)*5,y-7-s*5); ctx.stroke(); }
  } else {
    for (let i=-1;i<=1;i++){ ctx.beginPath(); ctx.moveTo(x+i*4, y);
      ctx.lineTo(x+i*4 + (s-.5)*6, y-8-s*5); ctx.stroke(); }
