First update state fields already. Add ambient update function. Where? after puff/toast maybe. But uses W/H, S.cam, BIOMES. Define after utils.

```js
function ambientUpdate(dt){
  const bi = biomeIdxAt(S.cam.y);
  const rate = [9, 16, 52, 12, 26][bi];
  if (S.amb.length < 150 && Math.random() < rate*dt){
    const p = { bi, t: 2 + Math.random()*2.5, r: 1.2 + Math.random()*2, wob: Math.random()*6.28 };
    p.tt = p.t;
    if (bi === 2){ // snow from above
      p.x = S.cam.x + (Math.random()*2-1)*W*0.8;
      p.y = S.cam.y - H*0.62;
      p.vx = -6 + Math.random()*12; p.vy = 45 + Math.random()*50;
      p.c = 'rgba(230,245,255,.85)';
    } else if (bi === 1){
      p.x = S.cam.x + (Math.random()*2-1)*W*0.8;
      p.y = S.cam.y + (Math.random()*2-1)*H*0.65;
      p.vx = 36 + Math.random()*46; p.vy = -6 + Math.random()*18;
      p.c = 'rgba(226,196,138,.5)';
    } else if (bi === 4){
      p.x = S.cam.x + (Math.random()*2-1)*W*0.8;
      p.y = S.cam.y + H*0.5 + Math.random()*H*0.2;
      p.vx = -12 + Math.random()*24; p.vy = -30 - Math.random()*40;
      p.c = 'rgba(255,140,60,.85)';
    } else if (bi === 3){
      p.x = S.cam.x + (Math.random()*2-1)*W*0.8;
      p.y = S.cam.y + (Math.random()*2-1)*H*0.65;
      p.vx = -8 + Math.random()*16; p.vy = -8 + Math.random()*16;
      p.c = 'rgba(160,230,180,.55)';
    } else {
      p.x = S.cam.x + (Math.random()*2-1)*W*0.8;
      p.y = S.cam.y + (Math.random()*2-1)*H*0.65;
      p.vx = 8 + Math.random()*24; p.vy = 22 + Math.random()*32;
      p.c = 'rgba(150,190,110,.7)';
    }
    S.amb.push(p);
  }
  for (let i = S.amb.length-1; i >= 0; i--){
    const p = S.amb[i]; p.t -= dt;
    if (p.t <= 0){ S.amb.splice(i,1); continue; }
    p.x += (p.vx + Math.sin(S.t*2+p.wob)*10)*dt;
    p.y += p.vy*dt;
  }
}
