const { chromium } = require('playwright');
const path = require('path');
const assert = (c, m) => { if (!c) throw new Error('FAIL: ' + m); console.log('ok -', m); };
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  const base = 'file://' + path.resolve('index.html');
  await page.goto(base);
  await page.waitForTimeout(400);

  const meta = await page.evaluate(() => ({
    goal: GOAL_M, biomes: BIOMES.map(b => b.name), span: BIOME_M, blend: BIOME_W,
    idx: [500, 1500, 2500, 3500, 4500].map(m => biomeIdxAt(-m * PPM)),
    mid: biomeMix(-1000 * PPM),
    before: biomeRgbAt(-930 * PPM),
    at: biomeRgbAt(-1000 * PPM),
    after: biomeRgbAt(-1070 * PPM),
    valley: BIOMES[0].ground, desert: BIOMES[1].ground,
  }));
  console.log(meta);
  assert(meta.goal === 5000, 'goal is 5000 m');
  assert(meta.biomes.length === 5, 'five biomes defined');
  assert(JSON.stringify(meta.idx) === JSON.stringify([0, 1, 2, 3, 4]), 'each 1000 m band maps to its biome');
  assert(meta.mid.a === 0 && meta.mid.b === 1 && Math.abs(meta.mid.t - 0.5) < 1e-6, 'boundary is a 50/50 blend');
  const between = (v, lo, hi) => v > Math.min(lo, hi) && v < Math.max(lo, hi);
  assert(between(meta.at[0], meta.valley[0], meta.desert[0]), 'blended ground is between both biome colours');

  // ground pixels differ from biome to biome
  const avgs = [];
  for (const m of [500, 1500, 2500, 3500, 4500]) {
    await page.goto(base + '?shot=biome&m=' + m + '&sim=20');
    await page.waitForTimeout(450);
    const px = await page.evaluate(() => {
      const c = document.getElementById('cv');
      const g = c.getContext('2d');
      const d = g.getImageData(10, Math.floor(c.height * 0.25), 24, 24).data;
      let r = 0, gg = 0, b = 0, n = 0;
      for (let i = 0; i < d.length; i += 4) { r += d[i]; gg += d[i + 1]; b += d[i + 2]; n++; }
      return [r / n, gg / n, b / n];
    });
    avgs.push(px);
    await page.screenshot({ path: '/tmp/opencode/b-' + m + '.png' });
  }
  console.log('ground averages:', avgs.map(a => a.map(v => v.toFixed(1)).join(',')));
  const distinct = new Set(avgs.map(a => a.map(v => Math.round(v / 8)).join(','))).size;
  assert(distinct >= 4, 'biome ground colours are visually distinct (' + distinct + ' groups)');

  // transition screenshots
  for (const m of [940, 1000, 1060]) {
    await page.goto(base + '?shot=biome&m=' + m + '&sim=20');
    await page.waitForTimeout(400);
    await page.screenshot({ path: '/tmp/opencode/bt-' + m + '.png' });
  }

  // banner on crossing
  await page.goto(base);
  await page.waitForTimeout(300);
  const banner = await page.evaluate(() => {
    S.train.moving = false; S.biomeIdx = 0; S.train.y = -990 * PPM;
    update(1 / 60);
    const first = document.getElementById('bioBanner').classList.contains('show');
    S.train.y = -1010 * PPM;
    update(1 / 60);
    return {
      first,
      show: document.getElementById('bioBanner').classList.contains('show'),
      title: document.getElementById('bioTitle').textContent,
      sub: document.getElementById('bioSub').textContent,
      hud: document.getElementById('hudBiome').textContent,
      next: document.getElementById('hudNext').textContent,
    };
  });
  console.log('banner:', banner);
  assert(!banner.first, 'no banner before boundary');
  assert(banner.show && banner.title === 'SUNSCORCHED BADLANDS', 'banner announces the new biome');
  assert(/BIOME 2 OF 5/.test(banner.sub), 'banner shows biome count');
  assert(/BADLANDS/.test(banner.hud), 'HUD shows current biome');
  assert(/m/.test(banner.next), 'HUD shows distance to next biome');

  // finish line at 5000 and signs near it
  const end = await page.evaluate(() => {
    const list = genChunk(Math.floor(-GOAL_M * PPM / CHUNK));
    return {
      finish: list.some(p => p.type === 'finish' && p.y === -GOAL_M * PPM),
      sign: list.some(p => p.type === 'sign' && p.m === GOAL_M),
    };
  });
  console.log('end props:', end);
  assert(end.finish, 'finish line exists at 5000 m');

  // win at 5000
  const win = await page.evaluate(() => {
    S.mode = 'play'; S.train.y = -GOAL_M * PPM - 5; S.train.moving = true;
    update(1 / 60);
    return { mode: S.mode, title: document.querySelector('#ovCard h2')?.textContent };
  });
  console.log('win:', win);
  assert(win.mode === 'win', 'reaching 5000 m wins');

  console.log(errors.length ? 'ERRORS:\n' + errors.join('\n') : 'no page errors');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

