const { chromium } = require('playwright');
const path = require('path');
const assert = (c, m) => { if (!c) throw new Error('FAIL: ' + m); console.log('ok -', m); };
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  const base = 'file://' + path.resolve('index.html');
  await page.goto(base);
  await page.waitForTimeout(400);

  assert(await page.locator('#ov').isVisible(), 'title overlay visible');
  await page.click('#go');
  await page.waitForTimeout(300);
  assert(await page.evaluate(() => S.mode === 'play' && S.player.aboard), 'playing and aboard');

  // build first workshop from cab
  await page.keyboard.press('b');
  await page.waitForTimeout(200);
  assert(await page.locator('#bmodal').isVisible(), 'BUILD opens without workshop');
  assert(/WORKSHOP first/.test(await page.locator('#bnote').innerText()), 'first-build hint visible');
  await page.locator('.bitem').first().locator('.bdo').tap();
  await page.waitForTimeout(250);
  const first = await page.evaluate(() => ({ carts: S.train.carts.map(c => c.type), paused: S.paused }));
  console.log('first build:', first);
  assert(first.carts[0] === 'workshop' && !first.paused, 'workshop built and game resumed');

  // walk into workshop and build plow
  await page.keyboard.down('ArrowDown');
  await page.waitForTimeout(850);
  await page.keyboard.up('ArrowDown');
  const zone = await page.evaluate(() => ({ inz: inZone('workshop'), open: canOpenBuild() }));
  assert(zone.inz && zone.open, 'workshop zone grants build access');
  await page.evaluate(() => { S.inv = { wood: 30, coal: 20, scrap: 30, food: 5 }; });
  await page.keyboard.press('b');
  await page.waitForTimeout(200);
  const names = await page.$$eval('.bitem b', bs => bs.map(b => b.textContent));
  assert(names.length === 5 && !names.includes('WORKSHOP'), 'owned workshop removed from catalogue');
  await page.locator('.bitem').first().locator('.bdo').tap();
  await page.waitForTimeout(200);
  assert(await page.evaluate(() => S.train.carts.some(c => c.type === 'plow')), 'plow built from workshop');
  await page.keyboard.press('Escape');
  await page.waitForTimeout(100);

  // cart effect checks: bunker max fuel, greenhouse, infirmary, turret, plow
  const effects = await page.evaluate(() => {
    S.train.carts.push({ type: 'bunker', store: 0, t: 0, cool: 0, aim: -Math.PI / 2 });
    const out = { fuelMax: fuelMax() };
    const gs = segs().find(s => s.type === 'green');
    if (!gs) S.train.carts.push({ type: 'green', store: 0, t: 0, cool: 0, aim: -Math.PI / 2 });
    const g2 = segs().find(s => s.type === 'green');
    S.player.ly = (g2.y0 + g2.y1) / 2; S.player.lx = 0;
    g2.ref.store = 3; g2.ref.t = 0;
    const f0 = S.inv.food; update(1 / 60);
    out.green = S.inv.food - f0;

    S.train.carts.push({ type: 'medic', store: 0, t: 0, cool: 0, aim: -Math.PI / 2 });
    const ms = segs().find(s => s.type === 'medic');
    S.player.ly = (ms.y0 + ms.y1) / 2; S.player.hp = 50;
    for (let i = 0; i < 60; i++) update(1 / 60);
    out.heal = S.player.hp > 50;

    const ts = segs().find(s => s.type === 'turret');
    if (!ts) S.train.carts.push({ type: 'turret', store: 0, t: 0, cool: 0, aim: -Math.PI / 2 });
    const t2 = segs().find(s => s.type === 'turret');
    const cy = S.train.y + (t2.y0 + t2.y1) / 2;
    S.train.moving = false;
    S.zombies = [{ x: 60, y: cy, hx: 60, hy: cy, hp: 3, wob: 0, t: 0 }];
    S.player.ly = 120;
    for (let i = 0; i < 330; i++) update(1 / 60);
    out.turret = S.zombies.length === 0;

    S.train.moving = true; S.train.fuel = 80;
    S.player.ly = 120;
    const chunk = genChunk(Math.floor(S.train.y / CHUNK));
    chunk.push({ type: 'debris', kind: 'log', x: 0, y: S.train.y - 40, hp: 2 });
    const sc = S.inv.scrap;
    for (let i = 0; i < 30; i++) update(1 / 60);
    out.plow = S.inv.scrap > sc;
    return out;
  });
  console.log('cart effects:', effects);
  assert(effects.fuelMax === 140, 'bunker raises max fuel to 140');
  assert(effects.green === 3, 'greenhouse harvests 3 food');
  assert(effects.heal, 'infirmary heals aboard');
  assert(effects.turret, 'turret kills nearby infected');
  assert(effects.plow, 'plow clears debris for scrap');

  // jump onto moving train
  const jump = await page.evaluate(() => {
    S.train.moving = true; S.train.fuel = 70;
    S.player.aboard = false; S.player.ly = 0; S.player.x = 32; S.player.y = S.train.y + 100;
    return { can: canBoard() };
  });
  assert(jump.can, 'boarding offered beside a moving train');
  await page.keyboard.press(' ');
  await page.waitForTimeout(150);
  assert(await page.evaluate(() => S.player.aboard), 'jumped onto moving train');

  // tree harvesting & decor filtering
  const res = await page.evaluate(() => {
    S.train.moving = false;
    const baseY = -4500;
    const list = genChunk(Math.floor(baseY / CHUNK));
    S.player.aboard = false; S.player.x = 0; S.player.y = baseY;
    const tree = { type: 'tree', x: 0, y: baseY + 32, amt: 2, s: .5 };
    list.push(tree);
    const found = nearestRes();
    const w0 = S.inv.wood;
    if (found) collect(found);
    const grass = { type: 'grass', x: 0, y: baseY, amt: 1 };
    list.push(grass);
    return { tree: found && found.type === 'tree', wood: S.inv.wood - w0, taken: !!tree.taken, grass: !nearestRes() };
  });
  console.log('resources:', res);
  assert(res.tree && res.wood === 3 && res.taken, 'tree can be chopped for wood');
  assert(res.grass, 'decor is not auto-collected');

  // eat + fuel
  const sys = await page.evaluate(() => {
    S.player.aboard = false; S.inv.food = 2; S.player.hp = 40; doEat();
    const eat = { hp: S.player.hp, food: S.inv.food };
    S.player.aboard = true; S.train.fuel = 20; S.inv.coal = 2; doFuel();
    return { eat, fuel: S.train.fuel, coal: S.inv.coal };
  });
  assert(sys.eat.hp === 75 && sys.eat.food === 1, 'eating heals 35');
  assert(sys.fuel === 60 && sys.coal === 1, 'coal refuels +40');

  // win at 5000 and retry
  await page.evaluate(() => { S.mode = 'play'; S.train.y = -GOAL_M * PPM - 1; S.train.moving = true; update(1 / 60); });
  await page.waitForTimeout(200);
  assert(await page.evaluate(() => S.mode === 'win'), 'win at 5000 m');
  assert(/5000/.test(await page.locator('#ovCard').innerText()), 'win card shows 5000 m goal');
  await page.click('#go');
  await page.waitForTimeout(120);
  const rr = await page.evaluate(() => ({ mode: S.mode, carts: S.train.carts.length, hp: S.player.hp,
    aboard: S.player.aboard, dist: document.getElementById('dist').textContent,
    biome: document.getElementById('hudBiome').textContent }));
  console.log('retry:', rr);
  assert(rr.mode === 'play' && rr.carts === 0 && rr.hp === 100 && rr.aboard, 'retry resets the run');
  assert(rr.dist.startsWith('0 '), 'distance HUD resets');
  assert(/GREEN VALLEY/.test(rr.biome), 'biome HUD resets');

  // death
  await page.evaluate(() => { S.mode = 'play'; S.player.hp = 5; damage(10); });
  await page.waitForTimeout(150);
  assert(await page.evaluate(() => S.mode === 'dead'), 'death state works');

  console.log(errors.length ? 'ERRORS:\n' + errors.join('\n') : 'no page errors');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

