function biomeRgbAt(y){
  const m = biomeMix(y);
  return m.t ? mix3(BIOMES[m.a].ground, BIOMES[m.b].ground, m.t) : BIOMES[m.a].ground;
}
function biomeWashAt(y){
  const m = biomeMix(y), A = BIOMES[m.a].wash, B = BIOMES[m.b].wash, t = m.t;
  return [A[0]+(B[0]-A[0])*t, A[1]+(B[1]-A[1])*t, A[2]+(B[2]-A[2])*t, A[3]+(B[3]-A[3])*t];
}

