const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('file://' + path.resolve('index.html'));
  await page.waitForTimeout(400);
  await page.click('#go');
  await page.waitForTimeout(200);

  const res = await page.evaluate(() => {
    S.mode = 'play';
    let err = null, draws = 0, maxAmb = 0, maxParts = 0;
    const marks = {};
    for (let i = 0; i < 34000; i++) {
      if (S.train.fuel < 45) S.train.fuel = 80;
      if (i % 900 === 0) S.inv = { wood: 50, coal: 20, scrap: 50, food: 20 };
      if (i === 600) { buildCart('workshop'); S.player.ly = 340; }
      if (i > 600 && i % 2400 === 0 && S.train.carts.length < 6) {
        for (const t of ['plow', 'bunker', 'green', 'turret', 'medic']) buildCart(t);
      }
      if (S.mode !== 'play') { S.mode = 'play'; }
      try { update(1 / 60); } catch (e) { err = 'U ' + e.message + ' @ ' + (e.stack || '').split('\n')[1]; break; }
      if (i % 120 === 0) {
        try { draw(); draws++; } catch (e) { err = 'D ' + e.message + ' @ ' + (e.stack || '').split('\n')[1]; break; }
        const b = biomeIdxAt(S.train.y);
        marks[b] = (marks[b] || 0) + 1;
        maxAmb = Math.max(maxAmb, S.amb.length);
        maxParts = Math.max(maxParts, S.parts.length);
      }
      if (S.train.y <= -GOAL_M * PPM) break;
    }
    return {
      err, draws, maxAmb, maxParts,
      dist: Math.floor(dist_m()), mode: S.mode,
      biome: biomeIdxAt(S.train.y),
      marks, chunks: chunks.size,
      carts: S.train.carts.map(c => c.type),
      hud: document.getElementById('hudBiome').textContent,
      next: document.getElementById('hudNext').textContent,
      errors: null,
    };
  });
  console.log(res);
  console.log(errors.length ? 'PAGE ERRORS:\n' + errors.join('\n') : 'no page errors');
  await page.screenshot({ path: '/tmp/opencode/n-end.png' });
  await browser.close();
  if (res.err) process.exit(1);
})();

