(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  await page.goto('file://' + path.resolve('index.html'));
  await page.waitForTimeout(400);
  await page.click('#go');
  await page.waitForTimeout(300);
  const before = await page.evaluate(() => S.player.ly);
  await page.mouse.move(100, 650); await page.mouse.down();
  await page.mouse.move(100, 600, { steps: 8 });
  await page.waitForTimeout(250);
  const during = await page.evaluate(() => ({ ly: S.player.ly, active: S.joy.active }));
  await page.mouse.up();
  console.log({ before, during });
  assert(during.active && during.ly < before - 20, 'mobile joystick walks forward on deck');
  await page.locator('#bBuild').tap();
  await page.waitForTimeout(150);
  assert(await page.locator('#bmodal').isVisible(), 'tapping BUILD opens workshop');
  await page.locator('.bitem').first().locator('.bdo').tap();
  await page.waitForTimeout(150);
