function spawnZs(zp){
  for (let i = 0; i < zp.n; i++){
    if (S.zombies.length > 42) break;
    const roll = Math.random();
    const v = roll < .16 ? 2 : roll < .44 ? 1 : 0, V = Z_VARIANTS[v];
    const pick = list => list[(Math.random()*list.length)|0];
    S.zombies.push({ x: zp.x + (Math.random()*2-1)*70, y: zp.y + (Math.random()*2-1)*70,
      hx: zp.x, hy: zp.y, hp: V.hp, maxHp: V.hp, wob: Math.random()*6.28, t: Math.random()*10,
      v, spdMul: V.spd, dmg: V.dmg, scale: V.scale, knock: V.knock, reach: V.reach,
      ang: Math.random()*6.28, skin: pick(V.skins), shirt: pick(V.shirts), eye: V.eyes,
      arm: v === 0 && Math.random() < .3 ? 1 : 0, flash: 0 });
  }
}
function killZombie(i, x, y, reward, hitColor){
  const z = S.zombies[i];
  S.zombies.splice(i,1); puff(x,y,hitColor || (z && z.skin) || '#4a6a3a', 10, 85);
  if (reward === 'scrap'){ S.inv.scrap++; addText(x,y,'+1 SCRAP','#9fd39f'); }
}
function zUpdate(dt){
  const p = S.player, spd = 62 + Math.min(45, dist_m()/45);
  for (let i = S.zombies.length-1; i >= 0; i--){
    const z = S.zombies[i]; z.t += dt;
    z.flash = Math.max(0, (z.flash || 0) - dt);
    const dpx = p.x - z.x, dpy = p.y - z.y, dp = Math.hypot(dpx,dpy) || 1;
    if (!p.aboard && dp < 360){
      const zs = spd * (z.spdMul || 1);
      z.x += dpx/dp * zs * dt; z.y += dpy/dp * zs * dt;
      z.ang = Math.atan2(dpy, dpx);
      if (dp < 25 && p.hurtT <= 0){ damage(z.dmg || 8); p.hurtT = .55; puff(p.x,p.y,'#a33',4,40); }
    } else {
      const a = Math.sin(z.t*.7 + z.wob)*2.4, hx = z.hx + Math.cos(a)*46, hy = z.hy + Math.sin(a)*46;
      const dx = hx-z.x, dy = hy-z.y, dd = Math.hypot(dx,dy) || 1;
      z.x += dx/dd * spd*.32 * dt; z.y += dy/dd * spd*.32 * dt;
      z.ang = Math.atan2(dy, dx);
    }
    if (p.aboard && Math.abs(z.y - S.cam.y) > 1900) S.zombies.splice(i,1);
    else if (Math.abs(z.y - S.cam.y) > 1900) S.zombies.splice(i,1);
  }
}

