/* ---------- depot houses ---------- */
function drawDepot(p){
  const x = p.x, y = p.y;
  const B = BIOMES[biomeIdxAt(p.y)];
  const rnd = mul32((Math.abs(x)*73 + Math.abs(y)*29 + 11) | 0);
  const style = Math.floor(Math.abs(y)/CHUNK) % 3;
  const bi = B.id, wall = B.depot, roof = B.roof || '#4f3d2a';
  const lit = shade(roof,.18), dark = shade(roof,-.26);
  const trim = shade(wall,-.28), trim2 = shade(wall,-.38);
  const back = y-64, ridge = y-20, eave = y+16, wallBot = y+52;
  const poly = (pts,fill)=>{
    ctx.fillStyle = fill; ctx.beginPath();
    pts.forEach(([px,py],i)=> i ? ctx.lineTo(px,py) : ctx.moveTo(px,py));
    ctx.closePath(); ctx.fill();
  };

  ctx.save();

  /* ground shadow and worn yard */
  ctx.fillStyle = 'rgba(0,0,0,.30)';
  ctx.beginPath(); ctx.ellipse(x+8, y+8, 98, 64, 0, 0, 6.3); ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,.11)';
  ctx.beginPath(); ctx.ellipse(x, y+56, 92, 22, 0, 0, 6.3); ctx.fill();

  /* side returns and front wall */
  fr(x-77, y-18, 10, 70, 2, trim);
  fr(x+67, y-18, 10, 70, 2, trim2);
  fr(x-77, y+2, 154, 50, 3, wall);
  ctx.strokeStyle = 'rgba(0,0,0,.16)'; ctx.lineWidth = 1;
  for (let sx=x-66; sx<x+70; sx+=11){
    ctx.beginPath(); ctx.moveTo(sx, y+16); ctx.lineTo(sx, wallBot); ctx.stroke();
  }
  fr(x-77, y+8, 7, 44, 1, trim);
  fr(x+70, y+8, 7, 44, 1, trim2);
  fr(x-78, y+46, 156, 6, 1, shade(wall,-.45));

  /* windows */
  const winGlow = (cx)=>{
    fr(cx-16, y+21, 32, 21, 2, '#3a2a1e');
    const g = ctx.createLinearGradient(0, y+23, 0, y+40);
    if (bi === 'ash'){
      g.addColorStop(0,'rgba(255,170,90,.95)'); g.addColorStop(1,'rgba(210,80,40,.9)');
    } else {
      g.addColorStop(0,'rgba(255,232,164,.96)'); g.addColorStop(1,'rgba(232,166,78,.9)');
    }
    ctx.fillStyle = g; ctx.fillRect(cx-13, y+24, 26, 15);
    ctx.strokeStyle = '#3a2a1e'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(cx, y+24); ctx.lineTo(cx, y+39);
    ctx.moveTo(cx-13, y+31); ctx.lineTo(cx+13, y+31); ctx.stroke();
    fr(cx-18, y+42, 36, 3, 1, '#2e2418');
    // shutters
    fr(cx-23, y+23, 5, 16, 1, trim2); fr(cx+18, y+23, 5, 16, 1, trim2);
    // sleepy light spill on the siding
    const sp = ctx.createLinearGradient(0, y+43, 0, wallBot);
    sp.addColorStop(0,'rgba(255,210,130,.16)'); sp.addColorStop(1,'rgba(255,210,130,0)');
    ctx.fillStyle = sp; ctx.fillRect(cx-15, y+43, 30, wallBot-y-43);
  };
  winGlow(x-45); winGlow(x+45);

  /* door and warm crack */
  fr(x-15, y+19, 30, 33, 2, '#2b211a');
  fr(x-12, y+22, 24, 28, 1, '#4b3522');
  ctx.strokeStyle = '#332418'; ctx.lineWidth = 1.5;
  ctx.strokeRect(x-8, y+25, 16, 9); ctx.strokeRect(x-8, y+37, 16, 10);
  ctx.fillStyle = '#d8b46a';
  ctx.beginPath(); ctx.arc(x+8, y+37, 1.6, 0, 6.3); ctx.fill();
  ctx.fillStyle = `rgba(255,196,110,${.16+Math.sin(S.t*2.2)*.04})`;
  ctx.fillRect(x-15, y+47, 30, 4);

  /* porch, rail and steps */
  fr(x-66, y+50, 132, 23, 2, shade(wall,-.30));
  ctx.strokeStyle = 'rgba(0,0,0,.22)'; ctx.lineWidth = 1;
  for (let py=y+55; py<y+72; py+=5){
    ctx.beginPath(); ctx.moveTo(x-64, py); ctx.lineTo(x+64, py); ctx.stroke();
  }
  const sp2 = ctx.createLinearGradient(0, y+50, 0, y+74);
  sp2.addColorStop(0,'rgba(255,214,140,.20)'); sp2.addColorStop(1,'rgba(255,214,140,0)');
  ctx.fillStyle = sp2; ctx.fillRect(x-15, y+50, 30, 24);
  ctx.strokeStyle = trim2; ctx.lineWidth = 2;
  for (const side of [-1,1]){
    const rx = x + side*61;
    ctx.beginPath(); ctx.moveTo(rx, y+54); ctx.lineTo(rx, y+70); ctx.stroke();
    fr(rx-2, y+52, 4, 4, 1, '#2e2418'); fr(rx-2, y+67, 4, 4, 1, '#2e2418');
  }
  fr(x-19, y+73, 38, 5, 1, shade(wall,-.38));
  fr(x-16, y+78, 32, 5, 1, shade(wall,-.46));

  /* roof */
  if (style === 0){
    poly([[x-88,y+back],[x+88,y+back],[x+80,y+ridge],[x-80,y+ridge]], dark);
    poly([[x-80,y+ridge],[x+80,y+ridge],[x+88,y+eave],[x-88,y+eave]], lit);
    ctx.strokeStyle = 'rgba(0,0,0,.17)'; ctx.lineWidth = 1.2;
    for (let i=1;i<=3;i++){
      const t = i/4, yy = lerp(y+back, y+ridge, t), hw = lerp(88,80,t);
      ctx.beginPath(); ctx.moveTo(x-hw,yy); ctx.lineTo(x+hw,yy); ctx.stroke();
    }
    for (let i=1;i<=4;i++){
      const t = i/5, yy = lerp(y+ridge, y+eave, t), hw = lerp(80,88,t);
      ctx.beginPath(); ctx.moveTo(x-hw,yy); ctx.lineTo(x+hw,yy); ctx.stroke();
      ctx.strokeStyle = 'rgba(0,0,0,.11)';
      for (let k=-4;k<=4;k++){
        if ((k+i) % 2) continue;
        const sx = x + k*hw/4.6;
        ctx.beginPath(); ctx.moveTo(sx,yy); ctx.lineTo(sx, yy+8); ctx.stroke();
      }
      ctx.strokeStyle = 'rgba(0,0,0,.17)';
    }
    fr(x-82, y+ridge-4, 164, 8, 4, shade(roof,.30));
    fr(x-89, y+eave-2, 178, 6, 3, shade(roof,-.42));
    ctx.strokeStyle = shade(roof,-.42); ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(x-88,y+back); ctx.lineTo(x-88,y+eave);
    ctx.moveTo(x+88,y+back); ctx.lineTo(x+88,y+eave); ctx.stroke();
  } else if (style === 1){
    poly([[x-88,y+back],[x,y-54],[x,y+8],[x-88,y+eave]], lit);
    poly([[x+88,y+back],[x,y-54],[x,y+8],[x+88,y+eave]], dark);
    ctx.strokeStyle = 'rgba(0,0,0,.16)'; ctx.lineWidth = 1.2;
    for (let i=1;i<=4;i++){
      const t = i/5, xx = lerp(x-88, x, t);
      const y0 = lerp(y+back, y-54, t), y1 = lerp(y+eave, y+8, t);
      ctx.beginPath(); ctx.moveTo(xx,y0); ctx.lineTo(xx,y1); ctx.stroke();
      const xx2 = lerp(x+88, x, t);
      const z0 = lerp(y+back, y-54, t), z1 = lerp(y+eave, y+8, t);
      ctx.beginPath(); ctx.moveTo(xx2,z0); ctx.lineTo(xx2,z1); ctx.stroke();
    }
    fr(x-3, y-55, 6, 64, 3, shade(roof,.30));
    fr(x-89, y+eave-2, 178, 6, 3, shade(roof,-.42));
    ctx.strokeStyle = shade(roof,-.42); ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(x-88,y+back); ctx.lineTo(x-88,y+eave);
    ctx.moveTo(x+88,y+back); ctx.lineTo(x+88,y+eave); ctx.stroke();
  } else {
    fr(x-88, y+back, 176, 80, 4, lit);
    ctx.strokeStyle = 'rgba(0,0,0,.10)'; ctx.lineWidth = 1;
    for (let sx=x-80; sx<=x+82; sx+=8){
      ctx.beginPath(); ctx.moveTo(sx,y+back+3); ctx.lineTo(sx,y+eave-3); ctx.stroke();
    }
    for (let sy=y+back+13; sy<y+eave; sy+=16){
      ctx.beginPath(); ctx.moveTo(x-85,sy); ctx.lineTo(x+85,sy); ctx.stroke();
    }
    ctx.strokeStyle = shade(roof,-.40); ctx.lineWidth = 3;
    rr(x-87, y+back+2, 174, 76, 3); ctx.stroke();
    // water tank on the flat roof
    ctx.fillStyle = '#5d6266'; ctx.beginPath(); ctx.arc(x+48,y-32,14,0,6.3); ctx.fill();
    ctx.strokeStyle = '#454a4e'; ctx.lineWidth = 1.6; ctx.stroke();
    ctx.strokeStyle = '#7e858a'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(x+48,y-32,10,0,6.3); ctx.stroke();
    ctx.fillStyle = '#8e959a'; ctx.beginPath(); ctx.arc(x+45,y-36,3.2,0,6.3); ctx.fill();
    ctx.fillStyle = '#3a3030'; ctx.fillRect(x-70,y-44,12,9);
    ctx.strokeStyle = '#8b929c'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(x+34,y-26); ctx.lineTo(x+8,y-14); ctx.stroke();
  }

  /* chimney + smoke */
  if (style !== 2 && rnd() > .28){
    const chx = x + (rnd() < .5 ? -38 : 38), chy = y - 34;
    fr(chx-9, chy-8, 18, 17, 2, '#5a4a42');
    ctx.strokeStyle = 'rgba(0,0,0,.22)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(chx-9,chy-2); ctx.lineTo(chx+9,chy-2);
    ctx.moveTo(chx-9,chy+4); ctx.lineTo(chx+9,chy+4); ctx.stroke();
    fr(chx-11, chy-10, 22, 4, 1, '#40332c');
    for (let k=0;k<3;k++){
      const ph = (S.t*.30 + k*.33) % 1;
      ctx.fillStyle = `rgba(215,215,208,${(1-ph)*.15})`;
      ctx.beginPath();
      ctx.arc(chx + Math.sin(S.t*.8 + k*2)*4 + ph*5, chy-14-ph*32, 4+ph*7, 0, 6.3);
      ctx.fill();
    }
  }

  /* biome dressing */
  if (bi === 'frozen'){
    ctx.fillStyle = 'rgba(240,250,255,.78)';
    ctx.beginPath(); ctx.ellipse(x, y+ridge-3, style===1?68:82, 4, 0, 0, 6.3); ctx.fill();
    ctx.fillStyle = 'rgba(240,250,255,.48)';
    for (let i=0;i<5;i++){
      ctx.beginPath();
      ctx.ellipse(x-58+rnd()*116, y-52+rnd()*48, 8+rnd()*13, 3+rnd()*2, 0, 0, 6.3);
      ctx.fill();
    }
    fr(x-88, y+eave-3, 176, 4, 2, 'rgba(240,250,255,.7)');
    ctx.fillStyle = 'rgba(200,232,248,.85)';
    for (let ix=x-78; ix<x+80; ix+=15){
      const h = 4 + rnd()*6;
      ctx.beginPath(); ctx.moveTo(ix-2, y+eave+2); ctx.lineTo(ix+2, y+eave+2);
      ctx.lineTo(ix, y+eave+2+h); ctx.closePath(); ctx.fill();
    }
  } else if (bi === 'swamp'){
    ctx.fillStyle = 'rgba(96,140,70,.26)';
    for (let i=0;i<4;i++){
      ctx.beginPath();
      ctx.ellipse(x-50+rnd()*100, y-50+rnd()*52, 9+rnd()*12, 4+rnd()*4, 0, 0, 6.3);
      ctx.fill();
    }
    ctx.strokeStyle = 'rgba(86,136,84,.62)'; ctx.lineWidth = 1.5;
    for (let ix=x-70; ix<x+72; ix+=19){
      ctx.beginPath(); ctx.moveTo(ix, y+eave);
      ctx.quadraticCurveTo(ix+2, y+eave+6, ix-1, y+eave+10); ctx.stroke();
    }
    ctx.fillStyle = 'rgba(24,52,48,.42)';
    ctx.beginPath(); ctx.ellipse(x-78, y+72, 22, 8, 0, 0, 6.3); ctx.fill();
  } else if (bi === 'valley'){
    ctx.strokeStyle = '#5c7f44'; ctx.lineWidth = 1.4;
    for (let i=0;i<9;i++){
      const gx = x-70+i*17 + rnd()*5;
      ctx.beginPath(); ctx.moveTo(gx, y+54);
      ctx.quadraticCurveTo(gx-2, y+49, gx-4, y+47); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(gx, y+54);
      ctx.quadraticCurveTo(gx+3, y+50, gx+5, y+48); ctx.stroke();
    }
    ctx.fillStyle = 'rgba(80,130,62,.20)';
    ctx.beginPath(); ctx.ellipse(x+52, y-44, 16, 7, 0, 0, 6.3); ctx.fill();
  } else if (bi === 'desert'){
    ctx.fillStyle = 'rgba(196,156,96,.34)';
    ctx.beginPath(); ctx.ellipse(x-72, y+54, 28, 8, 0, 0, 6.3); ctx.fill();
    ctx.beginPath(); ctx.ellipse(x+74, y+64, 24, 7, 0, 0, 6.3); ctx.fill();
    ctx.fillStyle = 'rgba(255,230,170,.10)';
    ctx.beginPath(); ctx.moveTo(x-38,y+back); ctx.lineTo(x-18,y+back);
    ctx.lineTo(x+22,y+eave); ctx.lineTo(x+6,y+eave); ctx.closePath(); ctx.fill();
  } else if (bi === 'ash'){
    ctx.strokeStyle = 'rgba(20,16,15,.42)'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(x-58,y-52); ctx.lineTo(x+18,y+6); ctx.stroke();
    ctx.strokeStyle = 'rgba(20,16,15,.28)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(x+46,y-46); ctx.lineTo(x+12,y-8); ctx.stroke();
    ctx.fillStyle = `rgba(255,110,40,${.14+Math.sin(S.t*4.5)*.05})`;
    ctx.fillRect(x-88, y+eave-2, 176, 3);
    ctx.fillStyle = 'rgba(96,84,80,.45)';
    ctx.beginPath(); ctx.ellipse(x-76, y+58, 18, 7, 0, 0, 6.3); ctx.fill();
  }

  /* yard clutter + lamp */
  if (rnd() > .42){
    const cx = x-72, cy = y+58;
    fr(cx-10, cy-8, 20, 16, 2, '#6b4e2e');
    ctx.strokeStyle = '#4a321c'; ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.moveTo(cx-8,cy-6); ctx.lineTo(cx+8,cy+6);
    ctx.moveTo(cx+8,cy-6); ctx.lineTo(cx-8,cy+6); ctx.stroke();
  }
  if (rnd() > .30){
    const bx = x+70, by = y+60;
    ctx.fillStyle = '#5b4a37'; ctx.beginPath(); ctx.arc(bx,by,9,0,6.3); ctx.fill();
    ctx.strokeStyle = '#8a8f95'; ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.arc(bx,by,6,0,6.3); ctx.stroke();
    ctx.beginPath(); ctx.arc(bx,by,2.6,0,6.3); ctx.stroke();
  }
  if (rnd() > .35){
    const lx = x+82, ly = y+48;
    const gl = ctx.createRadialGradient(lx,ly,2,lx,ly,34);
    gl.addColorStop(0,'rgba(255,205,110,.22)'); gl.addColorStop(1,'rgba(255,205,110,0)');
    ctx.fillStyle = gl; ctx.beginPath(); ctx.arc(lx,ly,34,0,6.3); ctx.fill();
    ctx.strokeStyle = '#2a2620'; ctx.lineWidth = 2.4;
    ctx.beginPath(); ctx.moveTo(lx,ly+8); ctx.lineTo(lx,ly-2); ctx.stroke();
    ctx.fillStyle = '#ffdf94';
    ctx.beginPath(); ctx.arc(lx,ly-4,3.4,0,6.3); ctx.fill();
    ctx.strokeStyle = '#3a3228'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(lx,ly-4,4.5,0,6.3); ctx.stroke();
  }

  ctx.restore();
}

/* ---------- player ---------- */
function drawPlayer(x,y,dir,atkT){
  const p = S.player;
  const amp = clamp(p.walkAmp || 0, 0, 1), ph = p.walk || 0;
  const step = Math.sin(ph) * 4.4 * amp;
  const idle = Math.sin(S.t*2.1) * .35;
  const bob = amp > .02 ? Math.abs(Math.sin(ph)) * 1.1 * amp : idle;
  const hurt = Math.max(0, p.hurtT || 0);
  const jolt = hurt > 0 ? Math.sin(S.t*55) * 1.7 * hurt : 0;

  ctx.fillStyle = 'rgba(0,0,0,.34)';
  ctx.beginPath(); ctx.ellipse(x+2, y+7, 11, 5.2, 0, 0, 6.3); ctx.fill();

  if (atkT > .22){
    const k = clamp((atkT-.22)/.2, 0, 1);
    ctx.strokeStyle = `rgba(255,238,190,${.2+k*.5})`; ctx.lineWidth = 4; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.arc(x, y, 29, dir-.95, dir+.8); ctx.stroke();
    ctx.strokeStyle = `rgba(255,255,225,${.3+k*.45})`; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(x, y, 24, dir-.55, dir+.35); ctx.stroke();
  }

  ctx.save();
  ctx.translate(x+jolt, y-bob);
  ctx.rotate(dir + Math.PI/2);

  /* feet */
  ctx.fillStyle = '#25272c';
  rr(-7.5, 3+step, 6, 7, 2); ctx.fill();
  rr(1.5, 3-step, 6, 7, 2); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,.10)';
  ctx.fillRect(-7.5, 3+step, 6, 1.6); ctx.fillRect(1.5, 3-step, 6, 1.6);

  /* coat tails */
  const sway = Math.sin(ph*2) * 2.6 * amp + idle;
  ctx.fillStyle = '#2f3d55';
  ctx.beginPath();
  ctx.moveTo(-8.8,-2);
  ctx.quadraticCurveTo(-12, 7+sway, -4.5, 13+sway);
  ctx.lineTo(4.5, 13-sway);
  ctx.quadraticCurveTo(12, 7-sway, 8.8,-2);
  ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#212d42'; ctx.lineWidth = 1.2; ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,.09)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(-4,2); ctx.lineTo(-2.5,11); ctx.moveTo(4,2); ctx.lineTo(2.5,11); ctx.stroke();

  /* backpack */
  fr(-5.5, 4, 11, 8.5, 3, '#6a4b2b');
  ctx.strokeStyle = '#4a321c'; ctx.lineWidth = 1; rr(-5.5,4,11,8.5,3); ctx.stroke();
  ctx.fillStyle = '#8a6a42'; ctx.fillRect(-4, 6, 8, 1.8);
  ctx.fillStyle = '#c9a24a'; ctx.fillRect(-1.4, 10.4, 2.8, 1.6);

  /* torso */
  ctx.fillStyle = '#3d4e6b';
  ctx.beginPath(); ctx.ellipse(0, 0, 8.6, 10, 0, 0, 6.3); ctx.fill();
  ctx.strokeStyle = '#243149'; ctx.lineWidth = 1.6; ctx.stroke();
  ctx.fillStyle = '#4b5f7f';
  ctx.beginPath(); ctx.arc(-7.1,-1.5,3.1,0,6.3); ctx.arc(7.1,-1.5,3.1,0,6.3); ctx.fill();
  ctx.strokeStyle = '#6a4c2e'; ctx.lineWidth = 2.6;
  ctx.beginPath(); ctx.moveTo(-6,-5.5); ctx.lineTo(6,3.5); ctx.stroke();
  ctx.fillStyle = '#d8b46a'; ctx.fillRect(-.9,-.9,1.8,1.8);
  ctx.strokeStyle = '#26202a'; ctx.lineWidth = 2.4;
  ctx.beginPath(); ctx.moveTo(-5.8,4.6); ctx.lineTo(5.8,4.6); ctx.stroke();

  /* scarf */
  ctx.strokeStyle = '#a5433a'; ctx.lineWidth = 3.2; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(-5.4,-1.2); ctx.lineTo(5.4,-1.2); ctx.stroke();
  const flap = Math.sin(S.t*3.4 + ph) * 2;
  ctx.fillStyle = '#a5433a';
  ctx.beginPath(); ctx.moveTo(4,-1); ctx.quadraticCurveTo(11, 2+flap, 12.5, 7+flap);
  ctx.lineTo(8.5,6.5+flap); ctx.quadraticCurveTo(8, 2, 4.5, 1); ctx.closePath(); ctx.fill();

  /* left arm reaching forward */
  ctx.strokeStyle = '#3d4e6b'; ctx.lineWidth = 4.4;
  ctx.beginPath(); ctx.moveTo(-7,-2); ctx.quadraticCurveTo(-8.6,-7.5, -5.2,-11.5); ctx.stroke();
  ctx.fillStyle = '#e8c39a';
  ctx.beginPath(); ctx.arc(-5.2,-11.5,2.3,0,6.3); ctx.fill();

  /* right arm + scrap weapon */
  ctx.strokeStyle = '#3d4e6b'; ctx.lineWidth = 4.4;
  const swinging = atkT > .22;
  const armX = swinging ? 5.2 : 7.2, armY = swinging ? -9.5 : -6;
  ctx.beginPath(); ctx.moveTo(7,-2); ctx.quadraticCurveTo(8.6,-6, armX,armY); ctx.stroke();
  ctx.fillStyle = '#e8c39a';
  ctx.beginPath(); ctx.arc(armX,armY,2.3,0,6.3); ctx.fill();
  const wAng = swinging ? lerp(-1.9, .75, clamp((0.42-atkT)/.2,0,1)) : -.62;
  ctx.save();
  ctx.translate(armX, armY); ctx.rotate(wAng);
  ctx.strokeStyle = '#7d858f'; ctx.lineWidth = 3.2; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(0,1); ctx.lineTo(0,-15); ctx.stroke();
  ctx.strokeStyle = 'rgba(240,245,250,.6)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(-.7,1); ctx.lineTo(-.7,-15); ctx.stroke();
  ctx.fillStyle = '#5a616b';
  ctx.beginPath(); ctx.arc(0,-15.5,3.3,0,6.3); ctx.fill();
  ctx.strokeStyle = '#9aa39c'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.arc(0,-15.5,3.3,0,6.3); ctx.stroke();
  ctx.restore();

  /* head, hair and cap */
  ctx.fillStyle = '#e8c39a';
  ctx.beginPath(); ctx.arc(0,-4.6,6.4,0,6.3); ctx.fill();
  ctx.strokeStyle = '#b98f68'; ctx.lineWidth = 1; ctx.stroke();
  ctx.fillStyle = '#2b2420';
  ctx.beginPath(); ctx.arc(0,-4.6,6.6,0,Math.PI); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#2e3a52';
  ctx.beginPath(); ctx.arc(0,-5.2,6.5,Math.PI*1.03,Math.PI*1.97); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#1f2738';
  rr(-5.6,-12.4,11.2,2.8,1.3); ctx.fill();
  ctx.fillStyle = 'rgba(130,160,200,.45)';
  ctx.fillRect(-5.2,-12.2,10.4,.8);
  ctx.fillStyle = '#20242a';
  ctx.beginPath(); ctx.arc(-1.9,-8.4,.95,0,6.3); ctx.arc(1.9,-8.4,.95,0,6.3); ctx.fill();
  ctx.fillStyle = '#6e4b35';
  ctx.beginPath(); ctx.arc(0,-6.2,1.1,0,6.3); ctx.fill();
  ctx.restore();

  if (hurt > 0){
    ctx.fillStyle = `rgba(215,55,45,${hurt*.5})`;
    ctx.beginPath(); ctx.arc(x, y, 12.5, 0, 6.3); ctx.fill();
  }
}

/* ---------- infected ---------- */
function drawZombie(z){
  const sc = z.scale || 1, t = z.t, wob = Math.sin(t*2.2 + z.wob)*.10;
  const gait = Math.sin(t*7 + z.wob)*2.4;
  const lunge = Math.sin(t*4.5 + z.wob)*1.8;
  ctx.fillStyle = 'rgba(0,0,0,.30)';
  ctx.beginPath(); ctx.ellipse(z.x+2, z.y+6, 11*sc, 5*sc, 0, 0, 6.3); ctx.fill();

  ctx.save();
  ctx.translate(z.x, z.y);
  ctx.rotate((z.ang || 0) + Math.PI/2 + wob);
  ctx.scale(sc, sc);
  ctx.lineCap = 'round';

  /* dragging feet */
  ctx.fillStyle = '#2d2822';
  rr(-6.2, 4+gait*.5, 5.4, 7.5, 2); ctx.fill();
  rr(1, 4-gait*.5, 5.4, 7.5, 2); ctx.fill();

  /* arms */
  const arm = (sx, ex, ey, bx, by)=>{
    ctx.strokeStyle = z.shirt; ctx.lineWidth = 4.4;
    ctx.beginPath(); ctx.moveTo(sx,-1.5); ctx.quadraticCurveTo(bx,by,ex,ey); ctx.stroke();
    ctx.fillStyle = z.skin;
    ctx.beginPath(); ctx.arc(ex,ey,2.2,0,6.3); ctx.fill();
    ctx.strokeStyle = 'rgba(60,20,20,.5)'; ctx.lineWidth = .9;
    ctx.beginPath(); ctx.moveTo(ex-1,ey-1); ctx.lineTo(ex-2.4,ey-2.2); ctx.stroke();
  };
  if (z.v === 2){
    arm(-6.6, -8.6-lunge, -11.4, -9.4, -7.2);
    arm(6.6, 8.6+lunge, -11.4, 9.4, -7.2);
  } else if (z.v === 1){
    arm(-6.2, -4.4-lunge*.5, -13.4, -8.4, -8);
    arm(6.2, 4.4+lunge*.5, -13.4, 8.4, -8);
  } else {
    if (!z.arm) arm(-6.2, -8.2, 5.5, -9.2, .5);
    arm(6.2, 4.2+lunge*.6, -12.8, 8.6, -7.6);
  }

  /* torso */
  ctx.fillStyle = z.shirt;
  ctx.beginPath(); ctx.ellipse(0,0,7.3,9.6,0,0,6.3); ctx.fill();
  ctx.strokeStyle = shade(z.shirt,-.35); ctx.lineWidth = 1.4; ctx.stroke();
  ctx.fillStyle = 'rgba(72,18,16,.42)';
  ctx.beginPath(); ctx.ellipse(2.2,1.6,3,4,0,0,6.3); ctx.fill();
  ctx.beginPath(); ctx.ellipse(-3.4,-4.5,2,2.6,0,0,6.3); ctx.fill();
  if (z.v !== 2){
    ctx.strokeStyle = 'rgba(226,218,184,.42)'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(-4,-1.2); ctx.lineTo(3.5,-1.2);
    ctx.moveTo(-3.4,1.8); ctx.lineTo(3,1.8); ctx.stroke();
  } else {
    ctx.strokeStyle = 'rgba(226,218,184,.30)'; ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.moveTo(-4.5,-2); ctx.lineTo(4,-2);
    ctx.moveTo(-3.6,1.2); ctx.lineTo(3.6,1.2); ctx.stroke();
    ctx.fillStyle = 'rgba(255,255,255,.10)';
    ctx.beginPath(); ctx.arc(-4.8,-5.4,2.4,0,6.3); ctx.fill();
  }

  /* wounds from recent hits */
  const wounds = (z.maxHp || 3) - z.hp;
  ctx.strokeStyle = 'rgba(120,24,20,.85)'; ctx.lineWidth = 1.6;
  for (let i=0;i<Math.min(3,wounds);i++){
    const wy = -4 + i*3.4;
    ctx.beginPath(); ctx.moveTo(-4.4,wy); ctx.lineTo(1.6,wy+2); ctx.stroke();
  }

  /* head */
  ctx.fillStyle = z.skin;
  ctx.beginPath(); ctx.arc(0,-9.4,5.7,0,6.3); ctx.fill();
  ctx.strokeStyle = shade(z.skin,-.34); ctx.lineWidth = 1.2; ctx.stroke();
  ctx.fillStyle = shade(z.skin,.05);
  ctx.beginPath(); ctx.ellipse(0,-6.5,3.5,2.3,0,0,6.3); ctx.fill();
  ctx.fillStyle = '#2a1917';
  ctx.beginPath(); ctx.ellipse(0,-7.2,2.2,1.2,0,0,6.3); ctx.fill();
  ctx.fillStyle = '#d8d0b4';
  ctx.beginPath(); ctx.arc(-1.2,-7.2,.5,0,6.3); ctx.arc(1.1,-7.2,.5,0,6.3); ctx.fill();
  // sunken glowing eyes
  ctx.fillStyle = z.eye;
  ctx.beginPath(); ctx.arc(-2,-11,1.15,0,6.3); ctx.arc(2,-11,1.15,0,6.3); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,220,.75)';
  ctx.beginPath(); ctx.arc(-2.3,-11.3,.4,0,6.3); ctx.arc(1.7,-11.3,.4,0,6.3); ctx.fill();
  // straggly hair
  ctx.strokeStyle = '#2a221c'; ctx.lineWidth = 1.2;
  for (let i=-2;i<=2;i++){
    ctx.beginPath(); ctx.moveTo(i*2.1,-13.6);
    ctx.lineTo(i*2.6 + Math.sin(t*3+i)*1.2, -16.2); ctx.stroke();
  }
  // blood at the mouth
  ctx.fillStyle = 'rgba(130,24,20,.65)';
  ctx.beginPath(); ctx.arc(-1.6,-5.4,.8,0,6.3); ctx.arc(1.4,-5.1,.7,0,6.3); ctx.fill();

  if (z.flash > 0){
    ctx.globalAlpha = Math.min(1, z.flash*4);
    ctx.fillStyle = '#ffd9c0';
    ctx.beginPath(); ctx.arc(0,0,9.4,0,6.3); ctx.fill();
    ctx.globalAlpha = 1;
  }
  ctx.restore();

  if (z.hp < (z.maxHp || 3)){
    const bw = 18, bh = 2.6, by = z.y - 22*sc;
    ctx.fillStyle = 'rgba(0,0,0,.55)'; ctx.fillRect(z.x-bw/2, by, bw, bh);
    ctx.fillStyle = z.v === 2 ? '#ff7a5a' : '#cfe878';
    ctx.fillRect(z.x-bw/2, by, bw * Math.max(0, z.hp/(z.maxHp||3)), bh);
  }
}

