    const d = list.find(p => p.type === 'depot');
    if (!d) return null;
    S.train.moving = false;
    S.train.y = d.y + 520;
    S.player.aboard = false;
    S.player.x = d.x; S.player.y = d.y + 112;
    S.player.pwx = S.player.x; S.player.pwy = S.player.y;
    S.player.dir = -Math.PI / 2;
    S.player.hp = 100;
    S.cam.x = S.player.x; S.cam.y = S.player.y;
    S.focusF = .55;
    S.zombies = [];
    return { x: d.x, y: d.y, style: Math.floor(Math.abs(d.y) / CHUNK) % 3, biome: biomeIdxAt(d.y) };
  }, ci);
};

