import pw from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.js';
const { chromium } = pw;

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: true,
  args: ['--no-sandbox', '--disable-gpu', '--hide-scrollbars'],
});
const page = await browser.newPage({ viewport: { width: 430, height: 932 }, deviceScaleFactor: 2 });
const problems = [];
page.on('pageerror', e => problems.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) problems.push('CONSOLE: ' + m.text()); });

await page.goto('http://localhost:3002/index.html?probe', { waitUntil: 'load' });
await page.click('#go');
await page.waitForTimeout(1900);

const placeAtDepot = async (ci) => await page.evaluate((ci) => {
  genChunk(ci);
  const list = chunks.get(ci);
  const d = list.find(p => p.type === 'depot');
  if (!d) return null;
  S.train.moving = false;
  S.train.y = d.y + 560;
  S.player.aboard = false;
  S.player.x = d.x; S.player.y = d.y + 118;
  S.player.pwx = S.player.x; S.player.pwy = S.player.y;
  S.player.dir = -Math.PI / 2;
  S.player.hp = 100;
  S.cam.x = S.player.x; S.cam.y = S.player.y;
  S.focusF = .55;
  S.zombies = [];
  return { x: d.x, y: d.y, style: Math.floor(Math.abs(d.y) / CHUNK) % 3,
    biome: BIOMES[biomeIdxAt(d.y)].id };
}, ci);

const shots = [];
for (const [name, ci] of [
  ['valley-style0', -4],
  ['valley-style1', -8],
  ['valley-style2', -12],
  ['frozen-style2', -60],
  ['swamp-style2', -84],
  ['ash-style2', -108],
]) {
  const depot = await placeAtDepot(ci);
  if (!depot) { problems.push('no depot for chunk ' + ci); continue; }
  await page.waitForTimeout(350);
  await page.screenshot({ path: `/tmp/opencode/depot-${name}.png` });
  shots.push([name, depot]);
}

// Player + all three infected variants, frozen in place
await page.evaluate(() => {
  S.train.moving = false;
  S.train.y = 4000;
  S.player.aboard = false;
  S.player.x = 0; S.player.y = 2000; S.player.dir = -Math.PI / 2;
  S.player.hp = 100; S.player.walkAmp = 1; S.player.walk = 1.1;
  S.cam.x = 0; S.cam.y = 2000; S.focusF = .5;
  S.zombies = [];
  const mk = (v, dx, dy) => {
    const V = Z_VARIANTS[v];
    S.zombies.push({ x: dx, y: 2000 + dy, hx: dx, hy: 2000 + dy, hp: V.hp, maxHp: V.hp,
      wob: v, t: 1, v, spdMul: 1, dmg: 0, scale: V.scale, knock: V.knock,
      ang: Math.PI / 2, skin: V.skins[0], shirt: V.shirts[0], eye: V.eyes, arm: 0, flash: 0 });
  };
  mk(0, -64, -38); mk(1, 0, -62); mk(2, 66, -38);
});
await page.waitForTimeout(80);
await page.evaluate(() => { S.paused = true; });
await page.screenshot({ path: '/tmp/opencode/actors-closeup.png', clip: { x: 80, y: 320, width: 270, height: 250 } });
await page.evaluate(() => { S.paused = false; });

// Interaction checks in open ground, away from the train
const checks = await page.evaluate(async () => {
  const out = {};
  S.train.y = 9000; S.train.moving = false;
  S.player.x = 0; S.player.y = 2000; S.player.aboard = false;
  S.player.dir = 0; S.player.atkT = 0; S.player.hurtT = 0;
  S.zombies = [];
  const before = S.player.x;
  S.keys.d = true;
  await new Promise(r => setTimeout(r, 300));
  S.keys.d = false;
  out.walked = S.player.x > before + 15;

  S.player.x = 0; S.player.y = 2000; S.zombies = [];
  S.zombies.push({ x: 34, y: 2000, hx: 34, hy: 2000,
    hp: 1, maxHp: 1, wob: 0, t: 0, v: 0, spdMul: 1, dmg: 0, scale: 1, knock: 26,
    ang: Math.PI, skin: '#6f8250', shirt: '#4c5a3c', eye: '#d9e878', arm: 0, flash: 0 });
  S.player.dir = 0; S.player.atkT = 0;
  doAct();
  await new Promise(r => setTimeout(r, 80));
  out.zombieKilled = S.zombies.length === 0;

  S.zombies = [];
  const z3 = { x: 40, y: 2000, hx: 40, hy: 2000, hp: 4, maxHp: 4, wob: 0, t: 0, v: 2,
    spdMul: 0.82, dmg: 13, scale: 1.2, knock: 16, ang: Math.PI, skin: '#5e7348',
    shirt: '#3e4a36', eye: '#ff6a4a', arm: 0, flash: 0 };
  S.zombies.push(z3);
  S.player.atkT = 0; doAct();
  await new Promise(r => setTimeout(r, 60));
  out.bruteTookHit = z3.hp === 3 && z3.flash > 0;
  out.mode = S.mode;
  out.paused = S.paused;
  return out;
});

// Walking pose close-up
await page.evaluate(() => {
  S.train.y = 9000;
  S.player.x = 0; S.player.y = 2000; S.zombies = [];
  S.cam.x = 0; S.cam.y = 2000; S.focusF = .5;
});
await page.keyboard.down('a');
await page.waitForTimeout(220);
await page.screenshot({ path: '/tmp/opencode/player-walk.png', clip: { x: 155, y: 410, width: 120, height: 120 } });
await page.keyboard.up('a');

console.log(JSON.stringify({ shots, checks, problems }, null, 2));
await browser.close();

