function drawPlayer(x,y,dir,atkT){
  const p = S.player;
  const amp = clamp(p.walkAmp || 0, 0, 1), ph = p.walk || 0;
  const step = Math.sin(ph) * 2.6 * amp;
  const idle = Math.sin(S.t*2.1) * .3;
  const bob = amp > .02 ? Math.abs(Math.sin(ph)) * .9 * amp : idle;
  const hurt = Math.max(0, p.hurtT || 0);
  const jolt = hurt > 0 ? Math.sin(S.t*55) * 1.7 * hurt : 0;

  /* soft drop shadow */
  ctx.fillStyle = 'rgba(0,0,0,.16)';
  ctx.beginPath(); ctx.ellipse(x+3, y+8, 15.5, 6.6, 0, 0, 6.3); ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,.28)';
  ctx.beginPath(); ctx.ellipse(x+1.5, y+6.4, 9.6, 4.4, 0, 0, 6.3); ctx.fill();

  /* swing trail */
  if (atkT > .22){
    const k = clamp((atkT-.22)/.2, 0, 1);
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(dir);
    const g = ctx.createRadialGradient(0,0,15,0,0,34);
    g.addColorStop(0,'rgba(255,246,214,0)');
    g.addColorStop(.6,`rgba(255,246,214,${.14+k*.24})`);
    g.addColorStop(1,'rgba(255,255,240,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(0,0,34,-.95,.55);
    ctx.arc(0,0,15,.55,-.95,true); ctx.closePath(); ctx.fill();
    ctx.strokeStyle = `rgba(255,252,232,${.22+k*.55})`;
    ctx.lineWidth = 2.8; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.arc(0,0,31,-.86,.44); ctx.stroke();
    ctx.restore();
  }

  ctx.save();
