```js
function mixHex(a, b, k){
  const na = parseInt(a.slice(1),16), nb = parseInt(b.slice(1),16);
  const ch = (n,s)=> (n>>s)&255;
  const r = Math.round(ch(na,16)+(ch(nb,16)-ch(na,16))*k);
  const g = Math.round(ch(na,8)+(ch(nb,8)-ch(na,8))*k);
  const bl = Math.round(ch(na,0)+(ch(nb,0)-ch(na,0))*k);
  return `rgb(${r},${g},${bl})`;
}
```

