  S.train.moving = false; S.train.y = 9000;
  S.player.aboard = false; S.player.x = -120; S.player.y = 2000;
  S.player.dir = -Math.PI / 2; S.player.hp = 100;
  S.player.walkAmp = 0; S.player.walk = 0; S.zombies = [];
