  document.querySelectorAll('#hud,#joy,#bAct,.hud,#toast,#banner,#bioBanner').forEach(e => e.style.display = 'none');
  DPR = 5;
  cv.width = W * 5; cv.height = H * 5;
  cv.style.width = (W * 5) + 'px'; cv.style.height = (H * 5) + 'px';
  cv.style.transformOrigin = '0 0';
  const sx = (W / 2) * 5, sy = (H * .5) * 5;
  cv.style.transform = `translate(${W / 2 - sx}px, ${H * .5 - sy}px)`;
});
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/opencode/s-player-idle.png', clip: { x: 120, y: 355, width: 190, height: 190 } });
await page.evaluate(() => { S.player.atkT = .40; });
await page.waitForTimeout(100);
await page.screenshot({ path: '/tmp/opencode/s-player-attack.png', clip: { x: 120, y: 355, width: 190, height: 190 } });
await page.evaluate(() => { S.player.atkT = 0; S.player.walkAmp = 1; S.player.walk = 1.3; S.player.dir = 0; });
await page.waitForTimeout(100);
await page.screenshot({ path: '/tmp/opencode/s-player-walk.png', clip: { x: 120, y: 355, width: 190, height: 190 } });

await page.evaluate(() => {
  S.player.x = -600; S.cam.x = 0; S.cam.y = 2000;
  S.zombies = [];
  const mk = (v, dx, dy) => {
    const V = Z_VARIANTS[v];
    S.zombies.push({ x: dx, y: 2000 + dy, hx: dx, hy: 2000 + dy, hp: V.hp, maxHp: V.hp,
      wob: 0, t: 1.4, v, spdMul: 0, dmg: 0, scale: V.scale, knock: V.knock,
