  };
  mk(0, -46, -16); mk(1, 0, -22); mk(2, 52, -12);
});
await page.waitForTimeout(150);
await page.screenshot({ path: '/tmp/opencode/s-zombies.png', clip: { x: 100, y: 385, width: 240, height: 160 } });

