  const r = {}, wait = ms => new Promise(z => setTimeout(z, ms));
  const reset = () => {
    S.mode = 'play'; S.paused = false; S.player.hp = 100; S.player.hurtT = 0;
    S.train.moving = false; S.train.fuel = 50; S.train.carts = []; S.train.y = 20000;
    S.player.aboard = false; S.player.x = 0; S.player.y = S.train.y + 260;
    S.player.dir = 0; S.zombies = []; S.inv = { wood: 8, coal: 8, scrap: 8, food: 2 };
    document.getElementById('ov').classList.add('hide');
  };

  /* fuel: standing next to the train with coal in the bag */
  reset();
  S.inv.coal = 5;
  r.fuelBefore = S.train.fuel;
  doFuel(); await wait(60);
  r.fuelAfter = S.train.fuel;
  r.fuelUsedCoal = S.inv.coal === 4;

  /* out of fuel message path */
  S.train.fuel = 0; S.inv.coal = 0;
  r.fuelEmptyToast = (doFuel(), document.getElementById('toast').textContent);

  /* eat food */
  reset(); S.player.hp = 40; S.inv.food = 3;
  doEat(); await wait(60);
  r.ate = S.player.hp > 40 && S.inv.food === 2;

  /* gather wood from a tree */
  reset();
  const tr = { type:'tree', x: 30, y: S.player.y, s: 1, taken: false, kind: 'valley' };
  chunks.set(2001, [tr]);
  if (typeof pChunk !== 'undefined') {}
  // use the real chunk store the world uses
  S.player.x = tr.x - 20; S.player.y = tr.y;
  // ensure prop is visible to the nearest-prop search
  const realChunk = Math.floor(tr.y / CHUNK);
  chunks.set(realChunk, (chunks.get(realChunk) || []).concat([tr]));
  r.gatherTarget = (() => { try { return nearestProp().type; } catch(e){ return 'ERR:' + e.message; } })();
  const w0 = S.inv.wood;
  pickProp && tr && null;
  try { gather(tr); } catch (e) { r.gatherErr = e.message; }
  r.wood = S.inv.wood >= w0;

  /* jump onto a moving train from beside the rails */
  reset();
  S.train.moving = true; S.train.fuel = 60;
  S.player.aboard = false; S.player.x = 14; S.player.y = S.train.y + 260;
  await wait(200);
  r.jumpedOn = S.player.aboard;

  /* debris on the rails stops the train unless a plow is fitted */
  reset();
  const dc = Math.floor((S.train.y - 40) / CHUNK);
  chunks.set(dc, (chunks.get(dc) || []).concat([{ type:'debris', x:0, y:S.train.y - 40, taken:false, s:1 }]));
  S.train.moving = true; S.train.fuel = 60;
  const yA = S.train.y;
  await wait(500);
  r.debrisHalt = !S.train.moving || S.train.y > yA;

  /* plow clears debris */
  reset();
  S.player.aboard = true; S.player.lx = 0; S.player.ly = 120;
  buildCart('workshop');
  for (let ly=200; ly<trainLen(); ly++){ const z = zoneAt(ly); if (z && z.type==='workshop'){ S.player.ly = (z.y0+z.y1)/2; break; } }
  S.inv = { wood: 40, coal: 20, scrap: 40, food: 6 };
  buildCart('plow');
  S.inv = { wood: 40, coal: 20, scrap: 40, food: 6 };
  buildCart('green'); buildCart('turret'); buildCart('medic');
  r.carts = S.train.carts.map(c => c.type);
  S.train.moving = true; S.train.fuel = 60; S.player.hp = 100;
  const f0 = S.inv.food, hp0 = S.player.hp;
  const zBefore = S.zombies.length;
  for (let i=0;i<600;i++) update(1/60);
