import pw from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.js';
const { chromium } = pw;
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu', '--hide-scrollbars'] });
const page = await browser.newPage({ viewport: { width: 430, height: 932 }, hasTouch: true });
const problems = [];
page.on('pageerror', e => problems.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) problems.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/index.html?probe', { waitUntil: 'load' });
await page.click('#go');
await page.waitForTimeout(500);

const out = await page.evaluate(async () => {
  const r = {}, wait = ms => new Promise(z => setTimeout(z, ms));
  const reset = (y = 20000) => {
    S.mode = 'play'; S.paused = false; S.player.hp = 100; S.player.hurtT = 0;
    S.train.moving = false; S.train.fuel = 50; S.train.carts = []; S.train.y = y;
    S.player.aboard = false; S.player.x = 0; S.player.y = y + 260;
    S.player.dir = 0; S.zombies = []; S.inv = { wood: 8, coal: 8, scrap: 8, food: 2 };
    document.getElementById('ov').classList.add('hide');
    document.getElementById('bmodal').classList.add('hide');
  };

  /* fuel */
  reset();
  S.inv.coal = 5;
  const f0 = S.train.fuel;
  doFuel(); await wait(60);
  r.fuel = { before: f0, after: Math.round(S.train.fuel), coal: S.inv.coal, ok: S.train.fuel > f0 && S.inv.coal === 4 };

  /* eating */
  reset(); S.player.hp = 40; S.inv.food = 3;
  doEat(); await wait(60);
  r.ate = { hp: Math.round(S.player.hp), food: S.inv.food, ok: S.player.hp > 40 && S.inv.food === 2 };

  /* gather a real generated resource */
  reset(4000);
  genChunk(Math.floor(4000 / CHUNK));
  genChunk(Math.floor(4000 / CHUNK) + 1);
  genChunk(Math.floor(4000 / CHUNK) - 1);
  let target = null;
  for (const p of propsInView(4000, 500)) if (RES_PICK[p.type] && p.amt > 0 && !p.taken) { target = p; break; }
  if (target){
    S.player.x = target.x + 18; S.player.y = target.y;
    target.taken = false;
    const found = nearestRes();
    const before = { ...S.inv };
    if (found) collect(found);
    r.gather = { type: target.type, found: !!found, before, after: { ...S.inv }, ok: !!found };
  } else r.gather = { ok: false, note: 'no resource prop generated' };

  /* jump onto a moving train */
  reset();
  S.train.moving = true; S.train.fuel = 60;
  S.player.x = 20; S.player.y = S.train.y + 260;
  await wait(240);
  r.jumpOn = { aboard: S.player.aboard, moving: S.train.moving };

  /* debris costs fuel without a plow */
  reset();
  const d = { type: 'debris', x: 0, y: S.train.y - 60, taken: false, s: 1, amt: 1 };
  const dc = Math.floor(d.y / CHUNK);
  chunks.set(dc, (chunks.get(dc) || []).concat([d]));
  S.train.moving = true; S.train.fuel = 50;
  const fd = S.train.fuel;
  for (let i = 0; i < 180; i++) update(1/60);
  r.debris = { taken: d.taken, fuelDropped: S.train.fuel < fd - 6, moving: S.train.moving };

  /* plow clears the same debris */
  reset();
  S.player.aboard = true; S.player.lx = 0; S.player.ly = 120;
  buildCart('workshop');
  for (let ly = 200; ly < trainLen(); ly++){ const z = zoneAt(ly); if (z && z.type === 'workshop'){ S.player.ly = (z.y0 + z.y1) / 2; break; } }
  S.inv = { wood: 60, coal: 30, scrap: 60, food: 8 };
  buildCart('plow');
  r.carts = S.train.carts.map(c => c.type);
  const d2 = { type: 'debris', x: 0, y: S.train.y - 60, taken: false, s: 1, amt: 1 };
  const dc2 = Math.floor(d2.y / CHUNK);
  chunks.set(dc2, (chunks.get(dc2) || []).concat([d2]));
  S.train.moving = true; S.train.fuel = 50;
  const scrap0 = S.inv.scrap;
  for (let i = 0; i < 180; i++) update(1/60);
  r.plow = { cleared: !!d2.taken, scrapGained: S.inv.scrap > scrap0, hasPlow: hasPlow() };

  /* cart functions: greenhouse, medic, turret */
  reset();
  S.player.aboard = true; S.player.lx = 0; S.player.ly = 120;
  buildCart('workshop');
  for (let ly = 200; ly < trainLen(); ly++){ const z = zoneAt(ly); if (z && z.type === 'workshop'){ S.player.ly = (z.y0 + z.y1) / 2; break; } }
  S.inv = { wood: 60, coal: 30, scrap: 60, food: 8 };
  buildCart('green'); buildCart('turret'); buildCart('medic');
  r.supportCarts = S.train.carts.map(c => c.type);
  // stand on the medic car and let green grow
  const gz = zoneAt(S.player.ly);
  S.player.hp = 60;
  S.train.moving = true; S.train.fuel = 80;
  S.player.aboard = true;
  for (let i = 0; i < 900; i++) update(1/60);
  r.healed = S.player.hp > 60;
  r.foodGrown = S.inv.food > 8;

  /* build gating */
  reset();
  buildCart('workshop');
  r.offTrainNoBuild = nCarts('workshop') === 0;

  /* mobile train button */
  reset();
  S.player.aboard = true; S.player.lx = 0; S.player.ly = 120;
  const fire = (id) => document.getElementById(id).dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, cancelable: true, pointerId: 9 }));
  fire('bTrain'); await wait(80);
  r.touchTrain = S.train.moving;
  fire('bTrain'); await wait(80);
  r.touchTrainStop = !S.train.moving;

  /* joystick movement */
  reset();
  const px = S.player.x;
  S.joy.active = true; S.joy.dx = 1; S.joy.dy = 0;
  await wait(320);
  S.joy.dx = 0;
  r.joystick = S.player.x > px + 10;

  return r;
});

out.problems = problems;
console.log(JSON.stringify(out, null, 2));
await browser.close();

