import pw from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.js';
const { chromium } = pw;
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu', '--hide-scrollbars'] });
const page = await browser.newPage({ viewport: { width: 430, height: 932 }, hasTouch: true });
const problems = [];
page.on('pageerror', e => problems.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) problems.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/index.html?probe', { waitUntil: 'load' });
await page.click('#go');
await page.waitForTimeout(500);

const out = await page.evaluate(async () => {
  const r = {}, wait = ms => new Promise(z => setTimeout(z, ms));
  const reset = (y = 20000) => {
    S.mode = 'play'; S.paused = false; S.player.hp = 100; S.player.hurtT = 0;
    S.train.moving = false; S.train.fuel = 50; S.train.carts = []; S.train.y = y;
    S.player.aboard = false; S.player.x = 0; S.player.y = y + 260;
    S.player.dir = 0; S.zombies = []; S.inv = { wood: 8, coal: 8, scrap: 8, food: 2 };
    document.getElementById('ov').classList.add('hide');
    document.getElementById('bmodal').classList.add('hide');
    S.smoke = []; S.parts = []; S.texts = []; S.beams = [];
  };
  const zoneCenter = type => {
    for (const s of segs()) if (s.type === type) return (s.y0 + s.y1) / 2;
    return null;
  };

  /* ---- fuel: must be aboard ---- */
  reset();
  S.inv.coal = 5;
  let f0 = S.train.fuel;
  doFuel();                       // on foot: refused
  r.fuelOnFoot = { msg: document.getElementById('toast').textContent, unchanged: S.train.fuel === f0 };
  S.player.aboard = true; S.player.lx = 0; S.player.ly = 120;
  doFuel(); await wait(40);
  r.fuelAboard = { before: f0, after: Math.round(S.train.fuel), coal: S.inv.coal, ok: S.train.fuel > f0 && S.inv.coal === 4 };

  /* ---- eating ---- */
  reset(); S.player.hp = 40; S.inv.food = 3;
  doEat(); await wait(40);
  r.ate = { hp: Math.round(S.player.hp), food: S.inv.food, ok: S.player.hp > 40 && S.inv.food === 2 };
  doEat(); await wait(40);
  r.ateAgain = { food: S.inv.food };

  /* ---- gathering a real resource ---- */
  reset(4000);
  for (const c of [Math.floor(4000/CHUNK)-1, Math.floor(4000/CHUNK), Math.floor(4000/CHUNK)+1]) genChunk(c);
  let target = null;
  for (const p of propsInView(4000, 520)) if (RES_PICK[p.type] && p.amt > 0 && !p.taken) { target = p; break; }
  if (target){
    S.player.x = target.x + 14; S.player.y = target.y;
    const found = nearestRes();
    const before = { ...S.inv };
    if (found) collect(found);
    r.gather = { type: target.type, found: !!found, before, after: { ...S.inv }, taken: target.taken };
  } else r.gather = { note: 'no resource generated' };

  /* ---- jump on a moving train ---- */
  reset();
  S.train.moving = true; S.train.fuel = 60;
  S.player.x = 22; S.player.y = S.train.y + 300;
  for (let i = 0; i < 6; i++){ update(1/60); }
  S.player.y = S.train.y + 260;      // stay alongside the passing consist
  doAct();
  r.jumpOn = { aboard: S.player.aboard, msg: document.getElementById('toast').textContent };

  /* ---- debris: fuel penalty without plow, cleared with plow ---- */
  reset();
  const mkDebris = y => {
    const d = { type: 'debris', x: 0, y, taken: false, s: 1, amt: 1 };
    const ci = Math.floor(y / CHUNK);
    chunks.set(ci, (chunks.get(ci) || []).concat([d]));
    return d;
  };
  let d1 = mkDebris(S.train.y - 60);
  S.train.moving = true; S.train.fuel = 50;
  let fd = S.train.fuel;
  for (let i = 0; i < 200; i++) update(1/60);
  r.debris = { taken: !!d1.taken, fuelLoss: Math.round(fd - S.train.fuel), plow: hasPlow() };

  reset();
  S.player.aboard = true; S.player.lx = 0; S.player.ly = 120;
  buildCart('workshop');
  S.inv = { wood: 60, coal: 30, scrap: 60, food: 8 };
  S.player.ly = zoneCenter('workshop');
  buildCart('plow');
  r.carts = S.train.carts.map(c => c.type);
  let d2 = mkDebris(S.train.y - 60);
  S.train.moving = true; S.train.fuel = 50;
  const scrap0 = S.inv.scrap;
  for (let i = 0; i < 200; i++) update(1/60);
  r.plow = { cleared: !!d2.taken, scrapGained: S.inv.scrap > scrap0, plow: hasPlow() };

  /* ---- support carts: greenhouse, medic, turret ---- */
  reset();
  S.player.aboard = true; S.player.lx = 0; S.player.ly = 120;
  buildCart('workshop');
  S.inv = { wood: 60, coal: 30, scrap: 60, food: 8 };
  S.player.ly = zoneCenter('workshop');
  buildCart('green'); buildCart('turret'); buildCart('medic');
  r.supportCarts = S.train.carts.map(c => c.type);
  const gz = zoneCenter('green'), mz = zoneCenter('medic');
  // grow food on the green car
  S.player.ly = gz;
  S.train.moving = true; S.train.fuel = 300;
  const food0 = S.inv.food;
  for (let i = 0; i < 1300; i++) update(1/60);
  r.green = { food: S.inv.food, gained: S.inv.food > food0, store: (segs().find(s => s.type === 'green') || {}).ref?.store };
  // heal on the medic car
  S.player.ly = mz; S.player.hp = 55;
  for (let i = 0; i < 400; i++) update(1/60);
  r.medic = { hp: Math.round(S.player.hp), healed: S.player.hp > 55 };
  // turret shoots a zombie near the train
  S.train.moving = false;
  const V = Z_VARIANTS[0];
  S.zombies = [{ x: 60, y: S.train.y + 320, hx: 60, hy: S.train.y + 320, hp: 3, maxHp: 3,
    wob: 0, t: 0, v: 0, spdMul: 0, dmg: 0, scale: 1, knock: 26, ang: 0,
    skin: V.skins[0], shirt: V.shirts[0], eye: V.eyes, arm: 0, flash: 0 }];
  for (let i = 0; i < 200; i++) update(1/60);
  r.turret = { hp: S.zombies.length ? S.zombies[0].hp : 'killed', engaged: S.zombies.length === 0 || S.zombies[0].hp < 3 };

  /* ---- gating ---- */
  reset();
  buildCart('workshop');
  r.offTrainNoBuild = nCarts('workshop') === 0;
  reset();
  S.player.aboard = true; S.player.lx = 0; S.player.ly = 120;
  buildCart('workshop');
  r.notInWorkshopNoBuild = nCarts('workshop') === 1 && S.train.carts.length === 1;
  S.player.ly = zoneCenter('workshop');
  S.inv = { wood: 60, coal: 30, scrap: 60, food: 8 };
  buildCart('bunker');
  r.inWorkshopBuild = S.train.carts.length === 2;

  /* ---- touch buttons ---- */
  reset();
  S.player.aboard = true; S.player.lx = 0; S.player.ly = 120;
  const fire = id => document.getElementById(id).dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, cancelable: true, pointerId: 9 }));
  fire('bTrain'); await wait(60);
  r.touchTrain = S.train.moving;
  fire('bTrain'); await wait(60);
  r.touchTrainStop = !S.train.moving;

  /* ---- joystick ---- */
  reset();
  const px = S.player.x;
  S.joy.active = true; S.joy.dx = 1; S.joy.dy = 0;
  await wait(320);
  S.joy.dx = 0; S.joy.active = false;
  r.joystick = S.player.x > px + 10;

  /* ---- desert / ash / ice / swamp lodgings exist along the route ---- */
  r.propCounts = (() => {
    const c = {};
    for (let ci = -20; ci > -130; ci -= 6){
      for (const p of (genChunk(ci), chunks.get(ci) || [])) c[p.type] = (c[p.type] || 0) + 1;
    }
    return c;
  })();

  return r;
});

out.problems = problems;
console.log(JSON.stringify(out, null, 2));
await browser.close();

