  ctx.fillStyle = 'rgba(0,0,0,.30)';
  ctx.beginPath(); ctx.ellipse(0, gy+10, 92, 15, 0, 0, 6.3); ctx.fill();
  // checkered threshold on the ground
  for (let i=0;i<10;i++){
    for (let j=0;j<2;j++){
      ctx.fillStyle = (i+j)%2 ? '#efe6d2' : '#b23a34';
      ctx.fillRect(-45+i*9, gy-9+j*7, 9, 7);
    }
  }
  // posts
  for (const sx of [-1,1]){
    fr(sx*bw-7, gy-postH, 14, postH+8, 3, '#464c52');
