const { chromium } = pw;
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu', '--hide-scrollbars'] });
const page = await browser.newPage({ viewport: { width: 430, height: 932 } });
const problems = [];
page.on('pageerror', e => problems.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) problems.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/index.html?probe', { waitUntil: 'load' });
await page.click('#go');
await page.waitForTimeout(500);

/* park just short of the arch, on foot, to inspect the gate */
await page.evaluate(() => {
  S.mode = 'play'; S.paused = false;
  document.getElementById('ov').classList.add('hide');
  S.train.y = -GOAL_M*PPM + 420; S.train.moving = false; S.train.fuel = 40;
  S.train.carts = []; S.player.aboard = false;
  S.player.x = -70; S.player.y = -GOAL_M*PPM + 250;
  S.player.dir = -Math.PI/2; S.hp = 100; S.player.hp = 100;
  S.cam.x = S.player.x; S.cam.y = S.player.y; S.focusF = .55;
  S.zombies = [];
  document.getElementById('bioBanner').classList.remove('show');
  S.toastT = 0; document.getElementById('toast').style.opacity = 0;
});
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/finish-gate.png' });

/* drive through to win */
await page.evaluate(() => {
  S.train.moving = true; S.train.fuel = 60;
  S.player.aboard = true; S.player.lx = 0; S.player.ly = 120;
});
await page.waitForTimeout(2600);
const mode = await page.evaluate(() => S.mode);
await page.screenshot({ path: '/tmp/opencode/finish-win.png' });

/* death screen */
await page.evaluate(() => {
  document.getElementById('ov').classList.add('hide');
  S.mode = 'play'; S.paused = false;
  S.train.y = 3000; S.train.moving = false; S.player.hp = 4;
  S.player.aboard = false; S.player.x = 0; S.player.y = 3260; S.cam.x = 0; S.cam.y = 3260;
  S.zombies = [{ x: 13, y: 3260, hx: 13, hy: 3260, hp: 5, maxHp: 5,
    wob: 0, t: 0, v: 2, spdMul: 1, dmg: 20, scale: 1.2, knock: 16, ang: 0,
    skin: '#6c8154', shirt: '#333a2c', eye: '#ff6a4a', arm: 0, flash: 0 }];
});
await page.waitForTimeout(800);
const mode2 = await page.evaluate(() => S.mode);
await page.screenshot({ path: '/tmp/opencode/finish-dead.png' });

console.log(JSON.stringify({ mode, mode2, problems }, null, 2));
await browser.close();

