import pw from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.js';
const { chromium } = pw;
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu', '--hide-scrollbars'] });
const page = await browser.newPage({ viewport: { width: 430, height: 932 } });
const problems = [];
page.on('pageerror', e => problems.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) problems.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/index.html?probe', { waitUntil: 'load' });

const r = {};
r.titleVisible = await page.evaluate(() => !document.getElementById('ov').classList.contains('hide'));
await page.click('#go');
await page.waitForTimeout(600);
r.started = await page.evaluate(() => ({
  mode: S.mode, moving: S.train.moving, y: Math.round(S.train.y),
  overlayHidden: document.getElementById('ov').classList.contains('hide'),
  hudDistance: document.getElementById('dist').textContent,
}));

/* win then restart */
await page.evaluate(() => { S.train.y = -GOAL_M*PPM - 5; });
await page.waitForTimeout(300);
r.winMode = await page.evaluate(() => S.mode);
await page.click('#go');
await page.waitForTimeout(400);
r.afterWinRestart = await page.evaluate(() => ({
  mode: S.mode, y: Math.round(S.train.y), moving: S.train.moving,
  carts: S.train.carts.length, hp: S.player.hp,
  overlayHidden: document.getElementById('ov').classList.contains('hide'),
  banner: document.getElementById('bioBanner').classList.contains('show'),
}));

/* death then restart */
await page.evaluate(() => {
  S.player.aboard = false; S.player.hp = 1;
  S.zombies = [{ x: 6, y: S.player.y, hx: 6, hy: S.player.y, hp: 5, maxHp: 5,
    wob: 0, t: 0, v: 2, spdMul: 1, dmg: 20, scale: 1, knock: 16, ang: 0,
    skin: '#6c8154', shirt: '#333a2c', eye: '#ff6a4a', arm: 0, flash: 0 }];
});
await page.waitForTimeout(500);
r.deadMode = await page.evaluate(() => S.mode);
await page.click('#go');
await page.waitForTimeout(400);
r.afterDeathRestart = await page.evaluate(() => ({
  mode: S.mode, hp: S.player.hp, moving: S.train.moving,
  overlayHidden: document.getElementById('ov').classList.contains('hide'),
}));

/* run + pause the train from the cab with keyboard */
await page.evaluate(() => {
  S.player.aboard = true; S.player.lx = 0; S.player.ly = 120;
  S.train.moving = false; S.train.fuel = 50; S.paused = false;
});
await page.keyboard.press('t');
await page.waitForTimeout(150);
r.keyboardTrain = await page.evaluate(() => S.train.moving);
await page.keyboard.press('t');

/* movement keys */
const x0 = await page.evaluate(() => { S.player.aboard = false; S.player.x = 0; S.player.y = 3000; S.cam.x = 0; S.cam.y = 3000; return S.player.x; });
await page.keyboard.down('d');
await page.waitForTimeout(350);
await page.keyboard.up('d');
r.keyboardWalk = await page.evaluate(x0 => S.player.x > x0 + 12, x0);

/* scroll lock */
r.noScroll = await page.evaluate(() => ({
  bodyScrollH: document.body.scrollHeight, innerH: innerHeight,
  overflow: getComputedStyle(document.documentElement).overflow,
  pos: getComputedStyle(document.body).position,
}));

console.log(JSON.stringify({ ...r, problems }, null, 2));
await browser.close();

import pw from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.js';
const { chromium } = pw;
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu', '--hide-scrollbars'] });
const page = await browser.newPage({ viewport: { width: 430, height: 932 } });
const problems = [];
page.on('pageerror', e => problems.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') problems.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/index.html?probe', { waitUntil: 'load' });
await page.click('#go');
await page.waitForTimeout(500);

const shots = [
  ['valley', 700],
  ['badlands', 14500],
  ['frozen', 25500],
  ['mire', 35500],
  ['ash', 45500],
];
for (const [name, py] of shots) {
  await page.evaluate((py) => {
    S.mode = 'play'; S.paused = false;
    document.getElementById('ov').classList.add('hide');
    const ci = Math.floor(py / CHUNK);
    for (const c of [ci-1, ci, ci+1]) genChunk(c);
    const props = chunks.get(ci) || [];
    const dep = props.find(p => p.type === 'depot');
    const x = dep ? dep.x : 0, y = dep ? dep.y : py;
    S.train.y = y + 640; S.train.moving = false; S.train.fuel = 70; S.train.carts = [];
    S.player.aboard = false; S.player.x = x - 70; S.player.y = y + 190;
    S.player.dir = -Math.PI / 2; S.player.hp = 100; S.player.walkAmp = .6; S.player.walk = .4;
    S.cam.x = S.player.x; S.cam.y = S.player.y; S.focusF = .55;
    S.zombies = [];
    document.getElementById('bioBanner').classList.remove('show'); S.biomeT = 0;
    S.toastT = 0; document.getElementById('toast').style.opacity = 0;
    S.biomeIdx = biomeIdxAt(S.train.y);
  }, py);
  await page.waitForTimeout(420);
  await page.screenshot({ path: `/tmp/opencode/biome-${name}.png` });
}

console.log(JSON.stringify({ problems }, null, 2));
await browser.close();

