import pw from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.js';
const { chromium } = pw;
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu', '--hide-scrollbars'] });
const sizes = [[360, 640], [390, 844], [430, 932], [820, 1180]];
const problems = [];
const report = [];
for (const [w, h] of sizes) {
  const page = await browser.newPage({ viewport: { width: w, height: h }, hasTouch: true, isMobile: w < 800 });
  page.on('pageerror', e => problems.push(`${w}x${h} PAGEERROR: ` + e.message));
  await page.goto('http://localhost:3002/index.html?probe', { waitUntil: 'load' });
  await page.click('#go');
  await page.waitForTimeout(400);
  await page.evaluate(() => {
    S.train.moving = false; S.train.fuel = 80;
    S.player.aboard = true; S.player.lx = 0; S.player.ly = 120;
    S.inv = { wood: 60, coal: 40, scrap: 60, food: 8 };
    buildCart('workshop');
    for (let ly = 200; ly < trainLen(); ly++){ const z = zoneAt(ly); if (z && z.type === 'workshop'){ S.player.ly = (z.y0+z.y1)/2; break; } }
    buildCart('plow'); buildCart('bunker'); buildCart('green'); buildCart('turret'); buildCart('medic');
    closeBuild(); toggleBuild();
  });
  await page.waitForTimeout(350);
  const m = await page.evaluate(() => {
    const list = document.getElementById('blist');
    const card = document.querySelector('#bmodal .card');
    const cr = card.getBoundingClientRect();
    return {
      rows: list.children.length,
      listScrolls: list.scrollHeight > list.clientHeight + 1,
      cardTop: Math.round(cr.top), cardBottom: Math.round(cr.bottom),
      vh: innerHeight, overflowX: document.documentElement.scrollWidth > innerWidth,
      btn: (() => { const b = document.getElementById('bAct').getBoundingClientRect(); return [Math.round(b.left), Math.round(b.top), Math.round(b.right), Math.round(b.bottom)]; })(),
    };
  });
  await page.screenshot({ path: `/tmp/opencode/build-${w}x${h}.png` });
  report.push({ size: `${w}x${h}`, ...m });
  await page.close();
}
console.log(JSON.stringify({ report, problems }, null, 2));
await browser.close();

